/* com.mtf.kibs.mapper.kibsMngMapper.selectBoothList */ SELECT seq , company_name_ko , company_name_en , booth_type , discount_type , discount_yn , registration_cnt , registration_fee , stand_alone_booth_cnt , stand_alone_booth_fee , assembly_booth_cnt , assembly_booth_fee , online_booth_cnt , online_booth_fee , discount_early_1 , discount_early_2 , discount_re_all , discount_scale_1 , discount_scale_2 , discount_scale_3 , discount_first , discount_leisure , booth_prc_sum , init_regi_dttm , final_regi_dttm FROM exhibitor WHERE 1=1
