/* com.mtf.kibs.mapper.kibsMngMapper.selectExhibitorNewBoothList */ SELECT en.seq , en.company_name_ko , en.company_name_en , en.booth_type , en.discount_type , en.discount_yn , en.registration_cnt , en.registration_fee , en.stand_alone_booth_cnt , en.stand_alone_booth_fee , en.assembly_booth_cnt , en.assembly_booth_fee , en.online_booth_cnt , en.online_booth_fee , en.discount_early_1 , en.discount_early_2 , en.discount_first_under_10 , en.discount_first_over_10 , en.discount_first , en.discount_re , en.discount_scale_1 , en.discount_scale_2 , en.discount_scale_3 , en.discount_scale_4 , en.discount_scale_5 , en.discount_scale_6 , en.discount_leisure , en.booth_prc_sum , en.discount_prc_sum , en.init_regi_dttm , en.final_regi_dttm , IF(( SELECT COUNT(*) FROM invoice_booth ib WHERE ib.exhibitor_seq = en.seq AND ib.del_yn = 'N') > 0, 'Y', 'N') AS invoiceYn FROM exhibitor_new en WHERE 1=1
AND en.transfer_year = #{transferYear}
