AND en.lang = #{lang}
AND en.approval_status = #{approvalStatus}
AND en.cancel_yn = #{cancelYn}
AND INSTR(en.booth_type,#{boothType}) > 0
AND en.discount_early_1 > 0
AND en.discount_early_2 > 0
AND en.discount_first_under_10 > 0
AND en.discount_first_over_10 > 0
AND en.discount_re > 0
AND en.discount_scale_1 > 0
AND en.discount_scale_2 > 0
AND en.discount_scale_3 > 0
AND en.discount_scale_4 > 0
AND en.discount_scale_5 > 0
AND en.discount_scale_6 > 0
