/* com.mtf.kibs.mapper.kibsMngMapper.selectUtilityList */ SELECT seq , company_name_ko , company_name_en , IFNULL(utility_jugan_cnt,0) as utility_jugan_cnt , IFNULL(utility_jugan_fee,0) as utility_jugan_fee , IFNULL(utility_day_cnt,0) as utility_day_cnt , IFNULL(utility_day_fee,0) as utility_day_fee , IFNULL(utility_compressed_air_cnt,0) as utility_compressed_air_cnt , IFNULL(utility_compressed_air_fee,0) as utility_compressed_air_fee , IFNULL(utility_water_basic_cnt,0) as utility_water_basic_cnt , IFNULL(utility_water_basic_fee,0) as utility_water_basic_fee , IFNULL(utility_internet_cnt,0) as utility_internet_cnt , IFNULL(utility_internet_fee,0) as utility_internet_fee , IFNULL(utility_pytex_new_cnt,0) as utility_pytex_new_cnt , IFNULL(utility_pytex_new_fee,0) as utility_pytex_new_fee , IFNULL(utility_pytex_re_cnt,0) as utility_pytex_re_cnt , IFNULL(utility_pytex_re_fee,0) as utility_pytex_re_fee , IFNULL(utility_barcode_cnt,0) as utility_barcode_cnt , IFNULL(utility_barcode_fee,0) as utility_barcode_fee , IFNULL(utility_prc_sum,0) as utility_prc_sum , init_regi_dttm , final_regi_dttm FROM exhibitor WHERE 1=1
AND transfer_year = #{transferYear}
