AND utility_internet_cnt > 0
AND utility_pytex_new_cnt > 0
AND utility_pytex_re_cnt > 0
AND utility_barcode_cnt > 0
ORDER BY (utility_jugan_cnt + utility_day_cnt + utility_compressed_air_cnt + utility_water_basic_cnt + utility_internet_cnt + utility_pytex_new_cnt + utility_pytex_re_cnt + utility_barcode_cnt) DESC , init_regi_dttm DESC

/* com.mtf.kibs.mapper.kibsMngMapper.selectExhibitorNewUtilityList */ SELECT en.seq , en.company_name_ko , en.company_name_en , en.booth_type , en.name , en.position , en.phone , en.registration_cnt , en.stand_alone_booth_cnt , en.assembly_booth_cnt , en.online_booth_cnt , IFNULL(en.utility_jugan_cnt,0) as utility_jugan_cnt , IFNULL(en.utility_jugan_fee,0) as utility_jugan_fee , IFNULL(en.utility_day_cnt,0) as utility_day_cnt , IFNULL(en.utility_day_fee,0) as utility_day_fee , IFNULL(en.utility_compressed_air_cnt,0) as utility_compressed_air_cnt , IFNULL(en.utility_compressed_air_fee,0) as utility_compressed_air_fee , IFNULL(en.utility_water_basic_cnt,0) as utility_water_basic_cnt , IFNULL(en.utility_water_basic_fee,0) as utility_water_basic_fee , IFNULL(en.utility_internet_cnt,0) as utility_internet_cnt , IFNULL(en.utility_internet_fee,0) as utility_internet_fee , IFNULL(en.utility_pytex_new_cnt,0) as utility_pytex_new_cnt , IFNULL(en.utility_pytex_new_fee,0) as utility_pytex_new_fee , IFNULL(en.utility_pytex_re_cnt,0) as utility_pytex_re_cnt , IFNULL(en.utility_pytex_re_fee,0) as utility_pytex_re_fee , IFNULL(en.utility_barcode_cnt,0) as utility_barcode_cnt , IFNULL(en.utility_barcode_fee,0) as utility_barcode_fee , IFNULL(en.utility_prc_sum,0) as utility_prc_sum , en.init_regi_dttm , en.final_regi_dttm , IF(( SELECT COUNT(*) FROM invoice_booth ib WHERE ib.exhibitor_seq = en.seq AND ib.del_yn = 'N') > 0, 'Y', 'N') AS invoiceYn FROM exhibitor_new en WHERE 1=1 AND (en.utility_jugan_cnt + en.utility_day_cnt + en.utility_compressed_air_cnt + en.utility_water_basic_cnt + en.utility_internet_cnt + en.utility_pytex_new_cnt + en.utility_pytex_re_cnt + en.utility_barcode_cnt) > 0
AND en.transfer_year = #{transferYear}
