/* com.mtf.kibs.mapper.kibsMngMapper.selectPassList */ SELECT e.seq , p.seq AS id , e.company_name_ko , e.company_name_en , p.pass_name , p.pass_first_name , p.pass_last_name , p.pass_position_ko , p.pass_position_en , p.pass_note , p.init_regi_dttm , p.final_regi_dttm FROM exhibitor e LEFT JOIN pass p ON e.seq = p.id WHERE 1=1
AND e.transfer_year = #{transferYear}
AND e.company_name_ko LIKE CONCAT('%',#{searchText},'%')
AND e.company_name_en LIKE CONCAT('%',#{searchText},'%')
