/* com.mtf.kibs.mapper.kibsMngMapper.selectExhibitorNewPassList */ SELECT e.seq , e.company_name_ko , e.company_name_en , e.name , e.position , e.phone , p_counts.totalPassCnt AS passCnt , e.init_regi_dttm , e.final_regi_dttm FROM exhibitor_new e INNER JOIN ( SELECT ex_seq , COUNT(*) AS totalPassCnt FROM pass_new GROUP BY ex_seq ) p_counts ON e.seq = p_counts.ex_seq WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM pass_new p WHERE p.ex_seq = e.seq )
AND e.transfer_year = #{transferYear}
