/* com.mtf.kibs.mapper.kibsMngMapper.selectMemberList */ SELECT r.gbn , r.seq , r.stat , r.id , r.nameKo , r.nameEn , r.email , r.initRegiDttm FROM ( SELECT '참가업체' as gbn /*유형*/ , e.seq , e.approval_status as stat /*상태*/ , e.id as id /*아이디*/ , e.company_name_ko as nameKo /*업체명(국문)*/ , e.company_name_en as nameEn /*업체명(영문)*/ , e.email as email /*이메일*/ , e.init_regi_dttm as initRegiDttm /*가입일자*/ FROM exhibitor_new e WHERE e.transfer_year = #{transferYear}
AND e.id LIKE CONCAT('%',#{searchText},'%')
AND e.company_name_ko LIKE CONCAT('%',#{searchText},'%')
AND e.company_name_en LIKE CONCAT('%',#{searchText},'%')
UNION ALL SELECT '참관객' as gbn /*유형*/ , v.seq , v.join_yn as stat /*상태*/ , '' as id /*아이디*/ , v.name as nameKo /*이름(국문)*/ , '' as nameEn /*이름(영문)*/ , CONCAT(v.email,'@',v.domain) as email /*이메일*/ , v.init_regi_dttm as initRegiDttm /*가입일자*/ FROM visitor v WHERE v.join_year = #{transferYear}
AND v.name LIKE CONCAT('%',#{searchText},'%')
AND v.name LIKE CONCAT('%',#{searchText},'%')
) r WHERE 1=1
AND r.gbn = #{gbn}
AND r.stat = #{stat}
ORDER BY r.initRegiDttm desc, r.nameKo asc

