/* com.mtf.kibs.mapper.KibsMngMapper.selectRequestList */ SELECT r.seq , r.emergency_yn , r.gbn , r.progress_step , r.complete_expect_date , r.title , (select count(*) from reply rp where rp.request_seq = r.seq) as replyCnt , r.writer , r.write_date , r.note , r.init_regi_pic , r.init_regi_dttm , r.final_regi_pic , r.final_regi_dttm FROM request r WHERE 1=1
AND r.title LIKE BINARY CONCAT('%',#{searchText},'%')
AND r.content LIKE BINARY CONCAT('%',#{searchText},'%')
AND r.gbn = #{gbn}
AND r.progress_step = #{progressStep}
AND r.emergency_yn = 'Y'
ORDER BY r.init_regi_dttm DESC

/* com.mtf.kibs.mapper.KibsMngMapper.getRequestSeq */
SELECT CONCAT('R', LPAD(next_val('request_seq'), '7', '0'))
FROM DUAL

mapper.insert:
/* com.mtf.kibs.mapper.KibsMngMapper.insertRequest */
INSERT INTO request
( seq
, gbn
, progress_step
, hope_closing_date
, complete_expect_date
, title
, content
, writer
, write_date
, note
, init_regi_pic
, init_regi_dttm
, final_regi_pic
, final_regi_dttm
)
VALUES
    ( #{seq}
    , #{gbn}
    , #{progressStep}
    , #{hopeClosingDate}
    , #{completeExpectDate}
    , #{title}
    , #{content}
    , #{writer}
    , #{writeDate}
    , #{note}
    , 'REQUEST'
    , DATE_FORMAT(NOW(), '%Y-%m-%d %T')
    , 'REQUEST'
    , DATE_FORMAT(NOW(), '%Y-%m-%d %T')
    )

mapper.update:
/* com.mtf.kibs.mapper.KibsMngMapper.updateRequest */
UPDATE request
SET gbn = #{gbn}
  , progress_step = #{progressStep}
  , hope_closing_date = #{hopeClosingDate}

  , complete_expect_date = #{completeExpectDate}

  , title = #{title}
  , content = #{content}
  , writer = #{writer}
  , write_date = #{writeDate}
  , final_regi_dttm = DATE_FORMAT(NOW(), '%Y-%m-%d %T')
WHERE seq = #{seq}

mapper.select:
/* com.mtf.kibs.mapper.KibsMngMapper.getReplySeq */
SELECT CONCAT('RP', LPAD(next_val('reply_seq'), '7', '0'))
FROM DUAL

mapper.insert:
/* com.mtf.kibs.mapper.KibsMngMapper.insertReply */
INSERT INTO reply
( seq
, request_seq
, depth_reply_no
, mo_reply_seq
, writer
, content
, write_date
, note
, init_regi_pic
, init_regi_dttm
, final_regi_pic
, final_regi_dttm
)
VALUES
    ( #{seq}
    , #{requestSeq}
    , #{depthReplyNo}
    , #{moReplySeq}
    , #{writer}
    , #{content}
    , DATE_FORMAT(NOW(), '%Y-%m-%d %T')
    , #{note}
    , 'REPLY'
    , DATE_FORMAT(NOW(), '%Y-%m-%d %T')
    , 'REPLY'
    , DATE_FORMAT(NOW(), '%Y-%m-%d %T')
    )

mapper.update:
/* com.mtf.kibs.mapper.KibsMngMapper.updateRequestProgressStep */
UPDATE request
SET progress_step = #{progressStep}
  , final_regi_dttm = DATE_FORMAT(NOW(), '%Y-%m-%d %T')
WHERE seq = #{seq}

/* com.mtf.kibs.mapper.KibsMngMapper.updateRequestCompleteExpect */
UPDATE request
SET complete_expect_date = #{completeExpectDate}
  , final_regi_dttm = DATE_FORMAT(NOW(), '%Y-%m-%d %T')
WHERE seq = #{seq}
